mapper.select:
SELECT r.rest
FROM reserverest AS r
WHERE r.id = #{reserverest_id}

mapper.insert:
INSERT INTO reserve_payment (
    merchant_uid,
    price,
    payment_method
) VALUES (
    #{merchant_uid},
    #{price},
    #{payment_method}
)

mapper.update:
UPDATE reserverest
SET rest = rest + 1
WHERE id = #{reserverest_id}

UPDATE reserveinfo
SET reservestatus='paycancel' WHERE
reserveinfo_num=#{reserveinfo_num}
